<?php namespace App\Repositories\Unit; use App\Models\Unit; class UnitRepository implements UnitRepositoryInterface {public function paginate(array $f){return Unit::query()->when($f['search']??null,fn($q,$s)=>$q->where(fn($x)=>$x->where('name','like',"%$s%")->orWhere('short_name','like',"%$s%")))->latest()->paginate(15)->withQueryString();} public function create(array $d):Unit{return Unit::create($d);} public function update(Unit $u,array $d):Unit{$u->update($d);return $u->refresh();} public function delete(Unit $u):void{$u->delete();}}